import { canonicalStyles, themeScript, viewerStyles } from "./site-shell.mjs";

const escapeHtml = (value) => String(value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;");
const formatDate = (value) => escapeHtml(value);
function navigation(config, prefix) {
  const links = [{ href: `${prefix}index.html`, label: config.pages.home.title }, { href: `${prefix}architecture-status/index.html`, label: "Architecture status", current: true }, ...config.pages.areas.map((area) => ({ href: `${prefix}${area.slug}/index.html`, label: area.title }))];
  return links.map((link) => `<li><a href="${escapeHtml(link.href)}"${link.current ? ' aria-current="page"' : ""}>${escapeHtml(link.label)}</a></li>`).join("\n");
}
function evidenceLink(check, browserRoot) {
  if (check.evidence.state === "missing") return `<span class="ds-muted">No evidence recorded: ${escapeHtml(check.evidence.reason)}</span>`;
  const href = new URL(check.evidence.path, browserRoot).href;
  return `<a href="${escapeHtml(href)}" data-ds-check-ignore="external-request" data-ds-check-reason="Repository evidence link; it is navigated by the reader and is not a remotely loaded artifact resource.">${escapeHtml(check.evidence.path)}</a> <span class="ds-muted">(${escapeHtml(check.evidence.source)}, ${escapeHtml(check.evidence.sha256)})</span>`;
}
function execution(check) {
  if (check.execution.state === "not-run") return `Not run: ${escapeHtml(check.execution.reason)}`;
  const range = `${formatDate(check.execution.startedAt)} → ${formatDate(check.execution.finishedAt)}`;
  return `${escapeHtml(check.execution.state)} · ${range}${check.execution.state === "completed" ? ` · exit ${escapeHtml(check.execution.exitCode)}` : ` · ${escapeHtml(check.execution.reason)}`}`;
}
function checkCard(check, browserRoot) {
  const result = check.result.state === "reported" ? `<p><strong>Result:</strong> ${escapeHtml(check.result.code)} — ${escapeHtml(check.result.label)}. ${escapeHtml(check.result.summary)}</p>${check.result.counts ? `<p><strong>Counts:</strong> ${check.result.counts.map((entry) => `${escapeHtml(entry.id)}: ${escapeHtml(entry.value)}`).join(", ")}</p>` : ""}${check.result.findingIds ? `<p><strong>Finding IDs:</strong> ${check.result.findingIds.map(escapeHtml).join(", ")}</p>` : ""}` : `<p><strong>Result:</strong> Unknown — ${escapeHtml(check.result.reason)}</p>`;
  const incomplete = check.incomplete ? `<p class="ds-status-banner ds-status-banner--warning" role="status"><strong>Incomplete evidence:</strong> ${escapeHtml([check.execution.state, check.evidence.state, check.freshness.state].join(" · "))}</p>` : "";
  return `<article class="ds-content-card"><p class="ds-content-card__tag">${escapeHtml(check.id)} · ${escapeHtml(check.freshness.state)}</p><h3>${escapeHtml(check.title)}</h3><p><strong>Authority:</strong> ${escapeHtml(check.authority)}</p><p><strong>Meaning:</strong> ${escapeHtml(check.resultMeaning)}</p>${result}<p><strong>Execution:</strong> ${execution(check)}</p><p><strong>Evidence:</strong> ${evidenceLink(check, browserRoot)}</p><p><strong>Observed:</strong> ${check.evidence.state === "present" ? `${formatDate(check.evidence.observedAt)} at ${escapeHtml(check.evidence.observedRevision)}` : "not available"}</p><p><strong>Limits:</strong> ${check.limits.length ? check.limits.map(escapeHtml).join("; ") : "None stated."}</p>${incomplete}</article>`;
}
export function renderArchitectureStatus({ config, status, paletteCss = "", assetPrefix = "../" }) {
  const repository = status.repository ?? { name: config.repository.name, revision: { commit: "not recorded", workingTree: "unknown" } };
  const present = status.state === "present";
  const cards = present ? status.checks.map((check) => checkCard(check, config.sourceLinks.browserRoot)).join("\n") : `<div class="ds-empty-state ds-surface"><h2>No architecture status snapshot</h2><p>A snapshot was configured but is not available. Run the deterministic checks and snapshot writer before building documentation.</p></div>`;
  const counts = present ? Object.entries(status.counts).map(([key, value]) => `<div class="ds-signal"><dt>${escapeHtml(key)}</dt><dd class="ds-signal__value">${escapeHtml(value)}</dd></div>`).join("") : "";
  return `<!doctype html>
<html data-ds-profile="rail-document" lang="en" data-theme="system"><head><meta charset="utf-8" /><meta name="viewport" content="width=device-width, initial-scale=1" /><meta name="color-scheme" content="light dark" /><title>${escapeHtml(config.document.title)} · Architecture status</title><script data-ds-theme>${themeScript}</script><style data-ds-palette="architecture-docs">${paletteCss}</style><style data-ds-canonical>${canonicalStyles}</style><style>${viewerStyles}.architecture-status-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(12rem,1fr));gap:var(--ds-space-2)}.architecture-status-card{display:grid;gap:var(--ds-space-2)}.architecture-status-card p{margin-block:0}@media(max-width:40rem){.architecture-status-grid{grid-template-columns:1fr}}</style></head><body class="ds-rail-document ds-ambient-field"><a class="ds-skip-link" href="#main">Skip to main content</a><header class="ds-top-chrome"><strong>Architecture docs · ${escapeHtml(config.repository.shortLabel ?? config.repository.name)}</strong><div class="ds-theme-controls ds-no-print" aria-label="Theme"><button type="button" data-theme-choice="system" aria-pressed="true">System</button><button type="button" data-theme-choice="light" aria-pressed="false">Light</button><button type="button" data-theme-choice="dark" aria-pressed="false">Dark</button></div></header><div class="ds-rail-document__layout"><nav class="ds-rail-document__rail" aria-label="Architecture documentation pages"><p class="ds-label">Architecture map</p><ul>${navigation(config, assetPrefix)}</ul></nav><main class="ds-rail-document__main" id="main"><section class="ds-statement-hero" aria-labelledby="status-title"><div class="ds-statement-hero__inner ds-shell"><p class="ds-kicker">Recorded deterministic evidence</p><h1 class="ds-display" id="status-title">Architecture status</h1><p class="ds-statement-hero__deck">Latest recorded check evidence for ${escapeHtml(repository.name)}. This page does not run checks or produce an aggregate architecture verdict.</p><p class="ds-status-banner ds-status-banner--warning" role="note"><strong>Authority stop:</strong> Results retain each check owner's meaning. Status evidence does not approve intent or change normative architecture assets.</p></div></section><section class="ds-rail-document__section" aria-labelledby="identity-title"><header class="ds-section-lead"><div><p class="ds-kicker">Snapshot identity</p><h2 class="ds-section-title" id="identity-title">Recorded repository and freshness</h2></div><p class="ds-section-lead__summary">All times and freshness statements below come from the normalized snapshot.</p></header><dl class="ds-signal-strip ds-signal-strip--metrics"><div class="ds-signal"><dt>Revision</dt><dd>${escapeHtml(repository.revision.commit)}</dd></div><div class="ds-signal"><dt>Working tree</dt><dd>${escapeHtml(repository.revision.workingTree)}</dd></div><div class="ds-signal"><dt>Generated</dt><dd>${present ? formatDate(status.generatedAt) : "not recorded"}</dd></div><div class="ds-signal"><dt>Snapshot</dt><dd>${present ? "present" : "absent"}</dd></div></dl>${present ? `<div class="architecture-status-grid">${counts}</div>` : ""}</section><section class="ds-rail-document__section" aria-labelledby="checks-title"><header class="ds-section-lead"><div><p class="ds-kicker">Independent check records</p><h2 class="ds-section-title" id="checks-title">Check-owned status</h2></div><p class="ds-section-lead__summary">Incomplete states remain visible independently: failed, missing, stale, not-run, and unknown are not collapsed.</p></header><div class="ds-card-grid architecture-status-grid">${cards}</div></section></main></div></body></html>`;
}
